INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000119',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn common German idioms set 1","Use Redewendungen naturally","Understand figurative language"],"explanation":{"intro":"Idioms (Redewendungen) are fixed expressions with figurative meanings — essential for natural-sounding German.","culturalNote":"German idioms often reflect cultural values: Daumen drücken (cross your fingers — actually press thumbs), nicht auf den Mund gefallen sein (not to be at a loss for words — not fallen on the mouth), Eulen nach Athen tragen (to carry owls to Athens — carry coals to Newcastle), alle Jubeljahre (once in a blue moon)."},"examples":[{"german":"Ich drücke dir die Daumen für die Prüfung!","english":"I''ll keep my fingers crossed for your exam! (lit: I press my thumbs for you)"},{"german":"Sie ist nicht auf den Mund gefallen und weiß immer eine Antwort.","english":"She is never at a loss for words and always knows an answer."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can understand and use common German idioms set 1."}}',
'{"items":[{"word":"jemandem die Daumen drücken","translation":"to keep fingers crossed for sb","pronunciation":"dee DOW-men DRÜK-en","example":"Daumen drücken!"},{"word":"nicht auf den Mund gefallen","translation":"never at a loss for words","pronunciation":"nikht owf den moond geh-FAL-en","example":"Nicht auf den Mund gefallen."},{"word":"auf der Hand liegen","translation":"to be obvious/clear","pronunciation":"owf dayr hant LEE-gen","example":"Das liegt auf der Hand."},{"word":"ins Schwarze treffen","translation":"to hit the nail on the head","pronunciation":"ins SHVAR-tseh TREF-en","example":"Ins Schwarze treffen."},{"word":"wie ein Buch reden","translation":"to talk non-stop","pronunciation":"vee yn bookh RAY-den","example":"Wie ein Buch reden."},{"word":"auf eigenen Beinen stehen","translation":"to stand on one''s own feet","pronunciation":"owf EY-gen-en BY-nen SHTAY-en","example":"Auf eigenen Beinen stehen."}]}',
'{"title":"Jemandem die Daumen drücken — to root for someone","pattern":"jemandem die Daumen drücken (dative person — to keep fingers crossed for someone)","explanation":"Jemandem die Daumen drücken = literally to press thumbs for someone = to keep one''s fingers crossed for them. German gesture: press the thumb INSIDE the fist (not two crossed fingers). Ich drücke dir die Daumen = I''m keeping my fingers crossed for you (dir = dative). Can also: Ich halte die Daumen für dich (less common). Very common before exams, auditions, or any challenge.","examples":[{"sentence":"Viel Glück bei deiner Prüfung — ich drücke dir die Daumen!","translation":"Good luck with your exam — I''m keeping my fingers crossed for you!"},{"sentence":"Wir alle drücken dir die Daumen für das Vorstellungsgespräch.","translation":"We all have our fingers crossed for your job interview."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Auf der Hand liegen'' means?","options":["to be obvious/clear","to be at hand","to be easy","to be visible"],"correctAnswer":"to be obvious/clear"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I''ll keep my fingers crossed for your exam!","options":["Ich drücke dir die Daumen für die Prüfung!","Viel Glück für die Prüfung!","Ich wünsche dir Erfolg!","Ich hoffe, du schaffst es!"],"correctAnswer":"Ich drücke dir die Daumen für die Prüfung!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir alle drücken dir die ___ für das Vorstellungsgespräch.","options":["Daumen","Finger","Hände","Fäuste"],"correctAnswer":"Daumen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Good luck with your exam — I''m keeping my fingers crossed!","wordBankItems":["Viel","Glück","bei","deiner","Prüfung","—","ich","drücke","dir","die","Daumen","!"],"correctAnswer":"Viel Glück bei deiner Prüfung — ich drücke dir die Daumen !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ins Schwarze treffen'' means?","options":["to hit the nail on the head","to hit the bull''s eye","to get it right","to be accurate"],"correctAnswer":"to hit the nail on the head"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000011a',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn common German idioms set 2","Use Redewendungen in context","Distinguish idioms from literal meaning"],"explanation":{"intro":"More German idioms for natural, fluent German — understanding these makes authentic speech and text much more accessible.","culturalNote":"German idioms often use concrete images: seinen Senf dazu geben (to give one''s mustard = to give one''s unsolicited opinion), den Nagel auf den Kopf treffen (to hit the nail on the head), jemandem auf den Schlips treten (to tread on someone''s tie = to offend)."},"examples":[{"german":"Er gibt immer seinen Senf dazu, auch wenn niemand ihn fragt.","english":"He always gives his two cents, even when nobody asks him."},{"german":"Das Fass zum Überlaufen bringen — das war der letzte Tropfen.","english":"That was the last straw — it made the barrel overflow."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can understand and use common German idioms set 2."}}',
'{"items":[{"word":"seinen Senf dazu geben","translation":"to give one''s two cents (unsolicited)","pronunciation":"ZY-nen zenf dah-TSOO GAY-ben","example":"Seinen Senf dazu geben."},{"word":"das Fass zum Überlaufen bringen","translation":"to be the last straw","pronunciation":"dahs fas tsoom Ü-ber-low-fen BRING-en","example":"Das Fass zum Überlaufen bringen."},{"word":"den Nagel auf den Kopf treffen","translation":"to hit the nail on the head","pronunciation":"den NAH-gel owf den kopf TREF-en","example":"Den Nagel treffen."},{"word":"auf den Schlips treten","translation":"to offend/step on toes","pronunciation":"owf den shlips TRAY-ten","example":"Auf den Schlips treten."},{"word":"unter die Arme greifen","translation":"to lend a hand/help out","pronunciation":"OON-ter dee AR-meh GRY-fen","example":"Unter die Arme greifen."},{"word":"keinen Finger krumm machen","translation":"to not lift a finger","pronunciation":"KY-nen FIN-ger kroom MAKH-en","example":"Keinen Finger krumm machen."}]}',
'{"title":"Das Fass zum Überlaufen bringen — the last straw","pattern":"das Fass zum Überlaufen bringen (idiom: to push past the breaking point)","explanation":"Das Fass zum Überlaufen bringen = to make the barrel overflow = to be the last straw / push someone to their limit. Das war der Tropfen, der das Fass zum Überlaufen gebracht hat = That was the drop that made the barrel overflow (= the last straw). A graphic idiom for accumulated frustration finally boiling over. Also: das Fass ist voll = the barrel is full = I''ve had enough.","examples":[{"sentence":"Sein Kommentar hat das Fass zum Überlaufen gebracht.","translation":"His comment was the last straw."},{"sentence":"Jetzt ist das Fass voll — ich kündige!","translation":"Now I''ve had enough — I''m resigning!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unter die Arme greifen'' means?","options":["to lend a hand","to support","to grab under the arms","to help along"],"correctAnswer":"to lend a hand"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"He always gives his two cents, even when nobody asks him.","options":["Er gibt immer seinen Senf dazu, auch wenn niemand ihn fragt.","Er sagt immer seine Meinung.","Er ist sehr meinungsstark.","Er fragt niemanden."],"correctAnswer":"Er gibt immer seinen Senf dazu, auch wenn niemand ihn fragt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sein Kommentar hat das Fass zum Überlaufen ___.","options":["gebracht","getragen","gehabt","gestellt"],"correctAnswer":"gebracht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Now I''ve had enough — I''m resigning!","wordBankItems":["Jetzt","ist","das","Fass","voll","—","ich","kündige","!"],"correctAnswer":"Jetzt ist das Fass voll — ich kündige !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Keinen Finger krumm machen'' means?","options":["to not lift a finger","to be lazy","to refuse","to do nothing"],"correctAnswer":"to not lift a finger"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000011b',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn German proverbs","Use Sprichwörter in context","Understand traditional wisdom"],"explanation":{"intro":"Proverbs (Sprichwörter) offer insight into German cultural values and make your language more colourful.","culturalNote":"German proverbs often reflect practical, hardworking values: Morgenstund hat Gold im Mund (the morning hour has gold in its mouth = the early bird catches the worm), Ende gut, alles gut (all''s well that ends well), was du heute kannst besorgen, das verschiebe nicht auf morgen (don''t put off until tomorrow what you can do today)."},"examples":[{"german":"Morgenstund hat Gold im Mund — deshalb stehe ich immer früh auf.","english":"The early bird catches the worm — that''s why I always get up early."},{"german":"Ende gut, alles gut — der Vortrag war schwierig, aber am Ende lief alles glatt.","english":"All''s well that ends well — the presentation was difficult but in the end everything went smoothly."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can understand and use German proverbs in context."}}',
'{"items":[{"word":"Morgenstund hat Gold im Mund","translation":"the early bird catches the worm","pronunciation":"MOR-gen-shtoond hat golt im mond","example":"Morgenstund!"},{"word":"Ende gut, alles gut","translation":"all''s well that ends well","pronunciation":"EN-deh goot, AL-es goot","example":"Ende gut, alles gut."},{"word":"Was man nicht im Kopf hat, muss man in den Beinen haben","translation":"if you don''t use your head, you''ll use your legs","pronunciation":"vas man nikht im kopf hat","example":"In den Beinen haben."},{"word":"Der Apfel fällt nicht weit vom Stamm","translation":"the apple doesn''t fall far from the tree","pronunciation":"dayr AP-fel fält nikht vyt fom shtam","example":"Apfel vom Stamm."},{"word":"glatt laufen","translation":"to go smoothly","pronunciation":"glat LOW-fen","example":"Alles lief glatt."},{"word":"verschieben auf","translation":"to postpone/put off","pronunciation":"fer-SHEE-ben owf","example":"Auf morgen verschieben."}]}',
'{"title":"Ende gut, alles gut — structure of German proverbs","pattern":"Proverbs often use subject-verb inversion or ellipsis — learn them as fixed chunks","explanation":"German proverbs (Sprichwörter) are fixed expressions — learn them as set phrases. Common structural patterns: Noun + Adjektiv in a compressed structure (Ende gut = when the end is good). Many use alliteration or rhyme: Morgenstund hat Gold im Mund. Usage: introduce with wie man sagt (as they say) or wie das Sprichwort sagt (as the proverb says). Can be used humorously or ironically.","examples":[{"sentence":"Er kommt immer zu spät. Wie man sagt: Pünktlichkeit ist die Höflichkeit der Könige.","translation":"He always comes late. As they say: punctuality is the politeness of kings."},{"sentence":"Am Ende hat alles geklappt — Ende gut, alles gut!","translation":"In the end everything worked out — all''s well that ends well!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Apfel fällt nicht weit vom Stamm'' means?","options":["the apple doesn''t fall far from the tree","like father like son","blood is thicker","family resemblance"],"correctAnswer":"the apple doesn''t fall far from the tree"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The early bird catches the worm — that''s why I always get up early.","options":["Morgenstund hat Gold im Mund — deshalb stehe ich immer früh auf.","Ich stehe früh auf.","Frühaufsteher sind erfolgreicher.","Gold verdient man am Morgen."],"correctAnswer":"Morgenstund hat Gold im Mund — deshalb stehe ich immer früh auf."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Am Ende hat alles geklappt — Ende gut, ___ gut!","options":["alles","alles ist","es ist alles","alles wäre"],"correctAnswer":"alles"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In the end everything worked out — all''s well that ends well!","wordBankItems":["Am","Ende","hat","alles","geklappt","—","Ende","gut",",","alles","gut","!"],"correctAnswer":"Am Ende hat alles geklappt — Ende gut , alles gut !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Glatt laufen'' means?","options":["to go smoothly","to run flat","to go well","to proceed"],"correctAnswer":"to go smoothly"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000011c',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn body-part idioms","Use Körperidiome naturally","Understand metaphorical body language"],"explanation":{"intro":"Body-part idioms (Körperidiome) are among the most common in German — knowing them makes authentic German much more accessible.","culturalNote":"German body idioms are vivid: jemandem auf die Zehen treten (to step on someone''s toes), die Hand im Spiel haben (to have a hand in it), jemanden im Auge behalten (to keep an eye on someone), einen kühlen Kopf bewahren (to keep a cool head)."},"examples":[{"german":"In dieser Situation musst du einen kühlen Kopf bewahren.","english":"In this situation you need to keep a cool head."},{"german":"Sie hat die Hand im Spiel — ich glaube, sie hat das organisiert.","english":"She has a hand in it — I think she organised it."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can understand and use body-part idioms in German."}}',
'{"items":[{"word":"einen kühlen Kopf bewahren","translation":"to keep a cool head","pronunciation":"EY-nen KÜ-len kopf beh-VAH-ren","example":"Kühlen Kopf bewahren."},{"word":"die Hand im Spiel haben","translation":"to have a hand in it","pronunciation":"dee hant im shpeel HAH-ben","example":"Die Hand im Spiel."},{"word":"jemanden im Auge behalten","translation":"to keep an eye on someone","pronunciation":"im OW-geh beh-HAL-ten","example":"Im Auge behalten."},{"word":"jemandem auf die Zehen treten","translation":"to step on someone''s toes","pronunciation":"owf dee TSAY-en TRAY-ten","example":"Auf die Zehen treten."},{"word":"jemanden auf dem Laufenden halten","translation":"to keep someone up to date","pronunciation":"owf dem LOW-fen-den HAL-ten","example":"Auf dem Laufenden halten."},{"word":"etwas unter die Lupe nehmen","translation":"to scrutinise/examine closely","pronunciation":"OON-ter dee LOO-peh NAY-men","example":"Unter die Lupe nehmen."}]}',
'{"title":"Bewahren — to preserve/keep/maintain","pattern":"etwas bewahren (to keep, preserve, maintain — a quality or thing under pressure)","explanation":"Bewahren = to keep, maintain, preserve (under pressure). Einen kühlen Kopf bewahren = to keep a cool head. Die Ruhe bewahren = to keep calm. Haltung bewahren = to maintain composure. Unlike behalten (to keep/retain an object), bewahren implies preserving something in the face of difficulty. Also: bewahren vor + dative = to protect from: Das hat mich vor einem Fehler bewahrt = That saved me from a mistake.","examples":[{"sentence":"Auch in der Krise hat sie die Fassung bewahrt.","translation":"Even in the crisis she maintained her composure."},{"sentence":"Diese Erfahrung hat ihn vor teuren Fehlern bewahrt.","translation":"This experience saved him from expensive mistakes."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Etwas unter die Lupe nehmen'' means?","options":["to scrutinise closely","to examine","to investigate","to inspect"],"correctAnswer":"to scrutinise closely"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In this situation you need to keep a cool head.","options":["In dieser Situation musst du einen kühlen Kopf bewahren.","In dieser Situation muss man ruhig sein.","Kühlen Kopf ist wichtig.","Bleib ruhig in dieser Situation."],"correctAnswer":"In dieser Situation musst du einen kühlen Kopf bewahren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Auch in der Krise hat sie die ___ bewahrt.","options":["Fassung","Fasset","Fasungen","Fassungen"],"correctAnswer":"Fassung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This experience saved him from expensive mistakes","wordBankItems":["Diese","Erfahrung","hat","ihn","vor","teuren","Fehlern","bewahrt","."],"correctAnswer":"Diese Erfahrung hat ihn vor teuren Fehlern bewahrt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Jemanden auf dem Laufenden halten'' means?","options":["to keep someone up to date","to inform regularly","to update someone","to brief someone"],"correctAnswer":"to keep someone up to date"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000011d',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn animal idioms","Use Tieridiome in context","Understand animal metaphors in German"],"explanation":{"intro":"Animal idioms (Tieridiome) are common and colourful in German — animals often represent human traits.","culturalNote":"German animal idioms: schwein haben (to have pig = to be lucky), den schwarzen Peter haben (to hold the black Peter = to be left holding the bag), eine Extrawurst braten (to fry an extra sausage = to get special treatment), mit dem Hühnern aufstehen (to rise with the chickens = to be an early riser)."},"examples":[{"german":"Du hast wirklich Schwein gehabt — das Vorstellungsgespräch hat geklappt!","english":"You were really lucky — the job interview worked out!"},{"german":"Er will immer eine Extrawurst gebraten haben.","english":"He always wants special treatment."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can understand and use animal idioms in German."}}',
'{"items":[{"word":"Schwein haben","translation":"to be lucky (lit: to have pig)","pronunciation":"SHVYN HAH-ben","example":"Schwein gehabt!"},{"word":"eine Extrawurst braten","translation":"to want special treatment","pronunciation":"EY-neh EX-trah-voorst BRAH-ten","example":"Extrawurst braten."},{"word":"den schwarzen Peter haben","translation":"to be left holding the bag","pronunciation":"den SHVAR-tsen PAY-ter HAH-ben","example":"Den schwarzen Peter haben."},{"word":"wie ein Elefant im Porzellanladen","translation":"like a bull in a china shop","pronunciation":"vee yn EL-eh-fant im por-tse-LAHN-lah-den","example":"Wie ein Elefant."},{"word":"mit den Wölfen heulen","translation":"to run with the pack","pronunciation":"mit den VÖL-fen HOY-len","example":"Mit den Wölfen heulen."},{"word":"da beißt die Maus keinen Faden ab","translation":"that''s final/there''s no arguing with it","pronunciation":"da byßt dee mows KY-nen FAH-den ap","example":"Da beißt die Maus."}]}',
'{"title":"Schwein haben — to be lucky (colloquial)","pattern":"Schwein haben (informal/colloquial — to be lucky, get a lucky break)","explanation":"Schwein haben = to be lucky (colloquial — from the pig as a luck symbol in German). Ich habe Schwein gehabt = I got lucky / I was lucky. Compare: Glück haben (more standard). Schwein also in: Schweinhund (derogatory), Schweinerei (mess/outrage). Note: Das ist eine Schweinerei! = That''s outrageous! Not the same as Schwein haben (lucky). The pig as luck symbol appears on New Year''s cards (Glücksschwein).","examples":[{"sentence":"Bei der Prüfung habe ich echt Schwein gehabt — eine Frage, die ich kannte!","translation":"In the exam I was really lucky — a question I knew!"},{"sentence":"Manchmal hat man Schwein, manchmal nicht.","translation":"Sometimes you''re lucky, sometimes not."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Wie ein Elefant im Porzellanladen'' means?","options":["like a bull in a china shop","clumsy","destructive","thoughtless"],"correctAnswer":"like a bull in a china shop"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"You were really lucky — the job interview worked out!","options":["Du hast wirklich Schwein gehabt — das Vorstellungsgespräch hat geklappt!","Das war Glück!","Das Gespräch lief gut.","Du hattest Erfolg."],"correctAnswer":"Du hast wirklich Schwein gehabt — das Vorstellungsgespräch hat geklappt!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bei der Prüfung habe ich echt Schwein ___.","options":["gehabt","gehabt haben","haben","gehaben"],"correctAnswer":"gehabt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Sometimes you''re lucky, sometimes not","wordBankItems":["Manchmal","hat","man","Schwein",",","manchmal","nicht","."],"correctAnswer":"Manchmal hat man Schwein , manchmal nicht ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Mit den Wölfen heulen'' means?","options":["to run with the pack","to follow the crowd","to howl at the moon","to behave wildly"],"correctAnswer":"to run with the pack"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000011e',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn colour idioms","Use Farbidiome in context","Understand colour symbolism in German"],"explanation":{"intro":"Colour idioms (Farbidiome) use colours figuratively in German — not always the same as in English.","culturalNote":"German colour idioms: blau sein (to be drunk — drunk as a Prussian blue dye worker), grünes Licht geben (to give the green light), jemandem nicht grün sein (not to be well-disposed towards sb — not green towards), schwarz auf weiß (in black and white = in writing), das Leben in Rosé sehen (to see life through rose-tinted glasses)."},"examples":[{"german":"Wir haben jetzt grünes Licht vom Chef — das Projekt kann beginnen.","english":"We now have the green light from the boss — the project can begin."},{"german":"Das steht schwarz auf weiß im Vertrag — du kannst es nicht leugnen.","english":"It''s there in black and white in the contract — you can''t deny it."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can understand and use colour idioms in German."}}',
'{"items":[{"word":"grünes Licht geben","translation":"to give the green light","pronunciation":"GRÜN-es likht GAY-ben","example":"Grünes Licht geben."},{"word":"schwarz auf weiß","translation":"in black and white/in writing","pronunciation":"SHVARTS owf vys","example":"Schwarz auf weiß."},{"word":"blau sein","translation":"to be drunk","pronunciation":"blow zyn","example":"Total blau sein."},{"word":"ins Blaue fahren","translation":"to go on a mystery trip","pronunciation":"ins BLOW-eh FAH-ren","example":"Ins Blaue fahren."},{"word":"jemandem nicht grün sein","translation":"not to like/be well-disposed to sb","pronunciation":"nikht grün zyn","example":"Nicht grün sein."},{"word":"leugnen","translation":"to deny","pronunciation":"LOYG-nen","example":"Etwas leugnen."}]}',
'{"title":"Schwarz auf Weiß — in black and white (in writing)","pattern":"Schwarz auf Weiß (idiom) — in black and white = in writing, documented, undeniable","explanation":"Schwarz auf Weiß = in black and white = formally written, documented, undeniable. Das steht schwarz auf weiß = That''s there in black and white. Ich will das schwarz auf weiß haben = I want that in writing. Very common in contracts and legal contexts. Also: Weiß in Weiß (white on white = camouflaged), Schwarz sehen (to be pessimistic, literally to see black).","examples":[{"sentence":"Ich möchte Ihre Zusage schwarz auf weiß.","translation":"I would like your confirmation in writing."},{"sentence":"Das steht doch schwarz auf weiß im Protokoll!","translation":"But it''s right there in black and white in the minutes!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Blau sein'' colloquially means?","options":["to be drunk","to be sad","to be carefree","to be naive"],"correctAnswer":"to be drunk"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"We now have the green light from the boss — the project can begin.","options":["Wir haben jetzt grünes Licht vom Chef — das Projekt kann beginnen.","Das Projekt wurde genehmigt.","Der Chef hat zugestimmt.","Wir dürfen beginnen."],"correctAnswer":"Wir haben jetzt grünes Licht vom Chef — das Projekt kann beginnen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich möchte Ihre Zusage schwarz auf ___.","options":["Weiß","weiß","Weis","weis"],"correctAnswer":"weiß"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: But it''s right there in black and white in the minutes!","wordBankItems":["Das","steht","doch","schwarz","auf","weiß","im","Protokoll","!"],"correctAnswer":"Das steht doch schwarz auf weiß im Protokoll !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ins Blaue fahren'' means?","options":["to go on a mystery trip","to drive into the blue","to go on holiday","to escape"],"correctAnswer":"to go on a mystery trip"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000011f',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn weather idioms","Use Wetteridiome in context","Understand weather metaphors"],"explanation":{"intro":"Weather idioms (Wetteridiome) use weather phenomena figuratively — very common in German everyday speech.","culturalNote":"German weather idioms: wie Hund und Katze sein (to fight like cat and dog), ins Wasser fallen (to fall through — like rain), einen Sturm im Wasserglas machen (to make a storm in a teacup), jemandem regnet es ins Gesicht (it rains in someone''s face = they have bad luck), das passt wie die Faust aufs Auge (fits like a fist in the eye = doesn''t fit at all, or — ironically — fits perfectly)."},"examples":[{"german":"Das Projekt ist ins Wasser gefallen — es wurde abgesagt.","english":"The project fell through — it was cancelled."},{"german":"Das ist doch ein Sturm im Wasserglas — das ist gar nicht so ernst.","english":"That''s a storm in a teacup — it''s not so serious at all."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can understand and use weather-related German idioms."}}',
'{"items":[{"word":"ins Wasser fallen","translation":"to fall through/be cancelled","pronunciation":"ins VAS-er FAL-en","example":"Ins Wasser gefallen."},{"word":"ein Sturm im Wasserglas","translation":"a storm in a teacup","pronunciation":"yn shtoom im VAS-er-glahs","example":"Sturm im Wasserglas."},{"word":"absagen","translation":"to cancel","pronunciation":"AP-zah-gen","example":"Eine Veranstaltung absagen."},{"word":"wetterabhängig","translation":"weather-dependent","pronunciation":"VET-er-ap-heng-ikh","example":"Wetterabhängige Pläne."},{"word":"das Wetter schlägt um","translation":"the weather turns","pronunciation":"dahs VET-er shläkt oom","example":"Das Wetter schlägt um."},{"word":"in jeden Topf passt ein Deckel","translation":"every pot has its lid (there''s someone for everyone)","pronunciation":"in YAY-den topf past yn DEK-el","example":"Topf und Deckel."}]}',
'{"title":"Ins Wasser fallen — to fall through (plan cancelled)","pattern":"ins Wasser fallen (idiom — plan/event falls through, gets cancelled)","explanation":"Ins Wasser fallen = to fall through, to be cancelled (event/plan). Der Ausflug ist ins Wasser gefallen = The trip fell through. Compare to English ''fell through'' — very close meaning. Also: etwas fällt flach = something falls flat. Related: absagen (to cancel — active decision), platzen (to burst = to collapse unexpectedly), scheitern (to fail/fall apart).","examples":[{"sentence":"Wegen des Regens ist das Konzert ins Wasser gefallen.","translation":"Because of the rain the concert fell through."},{"sentence":"Unsere Reisepläne sind leider ins Wasser gefallen.","translation":"Our travel plans unfortunately fell through."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ein Sturm im Wasserglas'' means?","options":["a storm in a teacup","an overreaction","a small crisis","much ado about nothing"],"correctAnswer":"a storm in a teacup"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The project fell through — it was cancelled.","options":["Das Projekt ist ins Wasser gefallen — es wurde abgesagt.","Das Projekt wurde abgesagt.","Leider klappt das Projekt nicht.","Das Projekt ist gescheitert."],"correctAnswer":"Das Projekt ist ins Wasser gefallen — es wurde abgesagt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Unsere Reisepläne sind leider ins Wasser ___.","options":["gefallen","gefallen worden","fallen","zu fallen"],"correctAnswer":"gefallen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Because of the rain the concert fell through","wordBankItems":["Wegen","des","Regens","ist","das","Konzert","ins","Wasser","gefallen","."],"correctAnswer":"Wegen des Regens ist das Konzert ins Wasser gefallen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Absagen'' means?","options":["to cancel","to call off","to decline","to postpone"],"correctAnswer":"to cancel"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000120',1,'APPROVED','PUBLISHED',
'{"objectives":["Deepen Konjunktiv II knowledge","Use Konjunktiv II for hypothetical and polite language","Apply to complex conditionals"],"explanation":{"intro":"Konjunktiv II deepens at B1 — covering more verbs, polite requests, and complex conditionals.","culturalNote":"Konjunktiv II is heavily used in polite German: Ich hätte gern... (I would like...), Dürfte ich...? (May I...?), Das wäre schön (That would be nice). Native speakers use it constantly — being able to use it naturally marks a key step toward fluency."},"examples":[{"german":"Wenn ich mehr Zeit hätte, würde ich täglich Deutsch lernen.","english":"If I had more time, I would study German every day."},{"german":"Das wäre wirklich toll — könntest du mir dabei helfen?","english":"That would be really great — could you help me with that?"}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can use Konjunktiv II fluently for polite requests and hypothetical scenarios."}}',
'{"items":[{"word":"Konjunktiv II — hätte/wäre/würde","translation":"subjunctive II — would have/would be/would","pronunciation":"KON-yoonk-teef tsvay","example":"Hätte, wäre, würde."},{"word":"höflich","translation":"polite","pronunciation":"HÖF-likh","example":"Höflich fragen."},{"word":"hypothetisch","translation":"hypothetical","pronunciation":"hyp-oh-TAY-tish","example":"Hypothetisch gesprochen."},{"word":"das Irrealis","translation":"irrealis/counterfactual","pronunciation":"dahs ir-ray-AH-lis","example":"Ein Irrealis."},{"word":"unerfüllt","translation":"unfulfilled/unrealized","pronunciation":"OON-er-fült","example":"Unerfüllter Wunsch."},{"word":"vorstellbar","translation":"imaginable/conceivable","pronunciation":"FOR-shtel-bar","example":"Kaum vorstellbar."}]}',
'{"title":"Konjunktiv II — synthesis and irregular forms","pattern":"haben→hätte, sein→wäre, werden→würde, wollen→wollte, können→könnte, müssen→müsste","explanation":"Key Konjunktiv II forms: haben→hätte, sein→wäre, werden→würde (most common), modal verbs retain umlaut if possible: können→könnte, müssen→müsste, dürfen→dürfte, wollen→wollte (no umlaut), sollen→sollte. Irregular: gehen→ginge, kommen→käme, wissen→wüsste, lassen→ließe. Most regular verbs use würde + infinitive rather than synthetic form: kaufen → würde kaufen (not käufe).","examples":[{"sentence":"Wenn ich du wäre, würde ich das anders machen.","translation":"If I were you, I would do that differently."},{"sentence":"Könntest du mir bitte ein Glas Wasser bringen?","translation":"Could you please bring me a glass of water?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"Konjunktiv II of ''haben'' is?","options":["hätte","hätten","habe","hat"],"correctAnswer":"hätte"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"If I had more time, I would study German every day.","options":["Wenn ich mehr Zeit hätte, würde ich täglich Deutsch lernen.","Wenn ich Zeit habe, lerne ich Deutsch.","Ich würde Deutsch lernen, wenn ich Zeit hätte.","Mit mehr Zeit lerne ich Deutsch."],"correctAnswer":"Wenn ich mehr Zeit hätte, würde ich täglich Deutsch lernen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wenn ich du ___, würde ich das anders machen.","options":["wäre","bin","war","sei"],"correctAnswer":"wäre"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Could you please bring me a glass of water?","wordBankItems":["Könntest","du","mir","bitte","ein","Glas","Wasser","bringen","?"],"correctAnswer":"Könntest du mir bitte ein Glas Wasser bringen ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"Konjunktiv II of ''können'' is?","options":["könnte","könte","kann","kannst"],"correctAnswer":"könnte"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000121',1,'APPROVED','PUBLISHED',
'{"objectives":["Use irreale Vergleiche (unreal comparisons)","Understand als ob/als wenn constructions","Use wie als comparison"],"explanation":{"intro":"Unreal comparison constructions using als ob (as if) allow describing situations that don''t match reality.","culturalNote":"Als ob constructions are very common in German speech and literature — they allow vivid description of appearance vs. reality. Thomas Mann, Kafka, and Brecht use these constructions extensively for irony and atmosphere."},"examples":[{"german":"Er tut so, als ob er alles wüsste.","english":"He acts as if he knew everything."},{"german":"Sie sieht aus, als wäre sie krank.","english":"She looks as if she were ill."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can form and use als ob / als wenn (as if) comparisons with Konjunktiv II."}}',
'{"items":[{"word":"als ob + Konjunktiv II","translation":"as if (with subjunctive II)","pronunciation":"als op","example":"Als ob er käme."},{"word":"so tun als ob","translation":"to act as if/pretend","pronunciation":"zo toon als op","example":"So tun als ob."},{"word":"aussehen als ob","translation":"to look as if","pronunciation":"OWS-zay-en als op","example":"Aussehen als ob."},{"word":"als wenn + Konjunktiv II","translation":"as if (alternative to als ob)","pronunciation":"als ven","example":"Als wenn das so wäre."},{"word":"auf den ersten Blick","translation":"at first glance","pronunciation":"owf den ERS-ten blik","example":"Auf den ersten Blick."},{"word":"der Eindruck","translation":"impression","pronunciation":"dayr YN-drook","example":"Den Eindruck machen."}]}',
'{"title":"Als ob + Konjunktiv II — as if (unreal comparison)","pattern":"... als ob + [Konjunktiv II clause with verb at end] — as if (something were the case)","explanation":"Als ob + Konjunktiv II: Er tut so, als ob er alles wüsste = He acts as if he knew everything (wüsste = Konj II of wissen). Als ob always triggers verb-final position AND Konjunktiv II. Shortcut: als + Konjunktiv II without ob: Er tut so, als wüsste er alles (inverted — verb directly after als). Verb in second position after als = Konjunktiv II, verb-final after als ob = same. Both are equally correct.","examples":[{"sentence":"Er spricht Deutsch, als ob er ein Muttersprachler wäre.","translation":"He speaks German as if he were a native speaker."},{"sentence":"Sie verhält sich, als hätte sie nichts getan.","translation":"She behaves as if she had done nothing."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Als ob'' is followed by?","options":["Konjunktiv II + verb final","Konjunktiv I","Indikativ","Infinitiv"],"correctAnswer":"Konjunktiv II + verb final"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"He acts as if he knew everything.","options":["Er tut so, als ob er alles wüsste.","Er weiß alles.","Er tut so, als wenn er alles weiß.","Er benimmt sich wie ein Experte."],"correctAnswer":"Er tut so, als ob er alles wüsste."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er spricht Deutsch, als ob er ein Muttersprachler ___.","options":["wäre","ist","sei","war"],"correctAnswer":"wäre"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She behaves as if she had done nothing","wordBankItems":["Sie","verhält","sich",",","als","hätte","sie","nichts","getan","."],"correctAnswer":"Sie verhält sich , als hätte sie nichts getan ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"Shortcut version of ''als ob er alles wüsste'' is?","options":["als wüsste er alles","als ob wüsste er alles","als er wüsste alles","als wissend er alles"],"correctAnswer":"als wüsste er alles"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000122',1,'APPROVED','PUBLISHED',
'{"objectives":["Use indirect/reported speech","Form indirekte Rede constructions","Distinguish Konjunktiv I and II in reported speech"],"explanation":{"intro":"Indirect speech (indirekte Rede) reports what someone said without quoting directly — essential for news, arguments, and academic writing.","culturalNote":"German newspapers use Konjunktiv I extensively for reported speech: Der Minister sagte, er sei für das Projekt (The minister said he was in favour of the project). This distinguishes reported speech from the journalist''s own position. In spoken German, Konjunktiv II is more common for reported speech."},"examples":[{"german":"Die Ministerin erklärte, sie wolle das Gesetz ändern.","english":"The minister explained that she wanted to change the law."},{"german":"Er sagte, er habe keine Zeit — dabei hatte er die ganze Zeit frei.","english":"He said he had no time — yet he was free the whole time."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can use indirect speech with Konjunktiv I/II in German."}}',
'{"items":[{"word":"behaupten","translation":"to claim/assert","pronunciation":"beh-HOWP-ten","example":"Etwas behaupten."},{"word":"erklären","translation":"to explain/declare","pronunciation":"er-KLÄY-ren","example":"Etwas erklären."},{"word":"ankündigen","translation":"to announce","pronunciation":"AN-kün-dee-gen","example":"Eine Maßnahme ankündigen."},{"word":"dabei","translation":"yet/even so/at the same time","pronunciation":"dah-BY","example":"Dabei hatte er Zeit."},{"word":"die indirekte Rede","translation":"reported/indirect speech","pronunciation":"dee in-dee-REK-teh RAY-deh","example":"Indirekte Rede."},{"word":"angeblich","translation":"allegedly/supposedly","pronunciation":"AN-gayp-likh","example":"Angeblich weiß er es."}]}',
'{"title":"Indirekte Rede — Konjunktiv I formation","pattern":"Er sagt, er sei / habe / komme — Konjunktiv I for reported speech","explanation":"Konjunktiv I = reportorial subjunctive (press/official register). Formation: infinitive stem + e endings: sein→sei, haben→habe, kommen→komme, wissen→wisse. When Konjunktiv I equals present indicative (we form, they form), substitute Konjunktiv II: Er sagt, er käme (not komme if identical). Main verb: say (sagen), claim (behaupten), explain (erklären), announce (ankündigen), think (meinen). Spoken: use Konjunktiv II or würde form.","examples":[{"sentence":"Der Sprecher sagte, die Lage sei stabil.","translation":"The spokesman said the situation was stable."},{"sentence":"Sie behauptete, sie habe die E-Mail nie erhalten.","translation":"She claimed she had never received the email."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"Konjunktiv I of ''sein'' is?","options":["sei","wäre","ist","soll"],"correctAnswer":"sei"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The minister explained that she wanted to change the law.","options":["Die Ministerin erklärte, sie wolle das Gesetz ändern.","Die Ministerin will das Gesetz ändern.","Die Ministerin sagte das.","Das Gesetz wird geändert."],"correctAnswer":"Die Ministerin erklärte, sie wolle das Gesetz ändern."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Sprecher sagte, die Lage ___ stabil.","options":["sei","wäre","ist","war"],"correctAnswer":"sei"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She claimed she had never received the email","wordBankItems":["Sie","behauptete",",","sie","habe","die","E-Mail","nie","erhalten","."],"correctAnswer":"Sie behauptete , sie habe die E-Mail nie erhalten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"In spoken German, reported speech more often uses?","options":["Konjunktiv II","Konjunktiv I","Indikativ","Infinitiv"],"correctAnswer":"Konjunktiv II"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000123',1,'APPROVED','PUBLISHED',
'{"objectives":["Master Konjunktiv I","Form all Konjunktiv I persons","Use Konjunktiv I in press and official texts"],"explanation":{"intro":"Konjunktiv I is the standard form for reported speech in German journalism, academic writing, and official reports.","culturalNote":"Reading German newspapers — especially Der Spiegel, Süddeutsche Zeitung, Frankfurter Allgemeine — Konjunktiv I appears constantly: Der Angeklagte gab an, er sei unschuldig = The accused stated he was innocent. Recognising it is essential for reading authentic German texts."},"examples":[{"german":"Das Unternehmen teilte mit, der Verlust sei höher als erwartet ausgefallen.","english":"The company announced that the loss had turned out higher than expected."},{"german":"Die Wissenschaftler berichteten, sie hätten neue Erkenntnisse gewonnen.","english":"The scientists reported that they had gained new findings."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can form and recognise Konjunktiv I in German press and official texts."}}',
'{"items":[{"word":"mitteilen","translation":"to inform/announce","pronunciation":"MIT-ty-len","example":"Etwas mitteilen."},{"word":"berichten","translation":"to report","pronunciation":"beh-RIKH-ten","example":"Über etwas berichten."},{"word":"die Erkenntnis","translation":"finding/realisation/insight","pronunciation":"dee er-KENT-nis","example":"Neue Erkenntnisse."},{"word":"ausfallen","translation":"to turn out/fall out","pronunciation":"OWS-fal-en","example":"Höher ausfallen."},{"word":"angeben","translation":"to state/claim","pronunciation":"AN-gay-ben","example":"Angeben, dass."},{"word":"laut","translation":"according to (preposition)","pronunciation":"lowt","example":"Laut Bericht."}]}',
'{"title":"Laut + genitive/dative — according to","pattern":"laut + genitive or dative (according to — for citing sources in indirect speech)","explanation":"Laut (according to) introduces a source in reported speech: Laut Bericht... = According to the report... Laut dem Sprecher... = According to the spokesman... Both dative and genitive work; in practice dative is more common in modern German. Combines well with indirect speech: Laut Polizei sei der Täter unbekannt (the police say the perpetrator is unknown). Also: laut Angaben + genitive (according to information from).","examples":[{"sentence":"Laut Nachrichtenagentur wurden drei Personen verletzt.","translation":"According to the news agency three people were injured."},{"sentence":"Laut dem Bericht hat sich die Situation verschlechert.","translation":"According to the report the situation has deteriorated."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"Konjunktiv I of ''haben'' is?","options":["habe","hätte","hat","habe"],"correctAnswer":"habe"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The company announced that the loss had turned out higher than expected.","options":["Das Unternehmen teilte mit, der Verlust sei höher als erwartet ausgefallen.","Das Unternehmen hatte mehr Verlust.","Der Verlust war hoch.","Das Unternehmen gab einen Verlust bekannt."],"correctAnswer":"Das Unternehmen teilte mit, der Verlust sei höher als erwartet ausgefallen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Laut Nachrichtenagentur wurden drei Personen ___.","options":["verletzt","verletzt worden","zu verletzen","verletzen"],"correctAnswer":"verletzt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: According to the report the situation has deteriorated","wordBankItems":["Laut","dem","Bericht","hat","sich","die","Situation","verschlechtert","."],"correctAnswer":"Laut dem Bericht hat sich die Situation verschlechtert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Mitteilen'' means?","options":["to inform/announce","to share","to communicate","to tell"],"correctAnswer":"to inform/announce"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000124',1,'APPROVED','PUBLISHED',
'{"objectives":["Use the Plusquamperfekt","Form past perfect constructions","Express earlier past events"],"explanation":{"intro":"The Plusquamperfekt (past perfect) expresses an action that occurred BEFORE another past action — the ''past of the past''.","culturalNote":"Plusquamperfekt is essential for narrating stories and explaining sequences of past events. It''s especially common in written German (novels, reports) and when using bevor (before), nachdem (after), als (when — past)."},"examples":[{"german":"Als er ankam, hatte sie bereits gegessen.","english":"When he arrived, she had already eaten."},{"german":"Nachdem wir alles gepackt hatten, fuhren wir los.","english":"After we had packed everything, we set off."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can use the Plusquamperfekt to express earlier past events in German."}}',
'{"items":[{"word":"das Plusquamperfekt","translation":"past perfect (past of past)","pronunciation":"dahs ploos-kvam-per-FEKT","example":"Das Plusquamperfekt."},{"word":"bereits","translation":"already (formal)","pronunciation":"beh-RYTS","example":"Bereits gegessen."},{"word":"nachdem","translation":"after (conjunction)","pronunciation":"NAKH-daym","example":"Nachdem er gegessen."},{"word":"bevor","translation":"before (conjunction)","pronunciation":"beh-FOR","example":"Bevor er ankam."},{"word":"losfahren","translation":"to set off/depart","pronunciation":"LOS-fah-ren","example":"Wir fuhren los."},{"word":"eintreten","translation":"to enter/occur/happen","pronunciation":"YN-tray-ten","example":"Bevor das eintrat."}]}',
'{"title":"Plusquamperfekt — formation and use","pattern":"hatte/war + Partizip II (had done/had been — earlier past event)","explanation":"Plusquamperfekt = hatte + Partizip II (for haben verbs) or war + Partizip II (for sein verbs): hatte gegessen (had eaten), war gegangen (had gone). Triggered by: nachdem + clause (after), bevor + clause (before), als (when — narrative sequence), bereits (already). Rule of thumb: if a sentence describes sequence in the past and one action came FIRST, put the earlier one in Plusquamperfekt.","examples":[{"sentence":"Nachdem er das Dokument gelesen hatte, unterschrieb er es.","translation":"After he had read the document, he signed it."},{"sentence":"Als ich ankam, war er schon gegangen.","translation":"When I arrived, he had already left."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"Plusquamperfekt of ''gehen'' is?","options":["war gegangen","hatte gegangen","ist gegangen","ging"],"correctAnswer":"war gegangen"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"When he arrived, she had already eaten.","options":["Als er ankam, hatte sie bereits gegessen.","Als er ankam, aß sie schon.","Er kam an und sie aß.","Sie hatte gegessen als er ankam."],"correctAnswer":"Als er ankam, hatte sie bereits gegessen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nachdem er das Dokument gelesen ___, unterschrieb er es.","options":["hatte","hat","wird","habe"],"correctAnswer":"hatte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: When I arrived, he had already left","wordBankItems":["Als","ich","ankam",",","war","er","schon","gegangen","."],"correctAnswer":"Als ich ankam , war er schon gegangen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Nachdem'' requires which tense?","options":["Plusquamperfekt in the subordinate clause","Perfekt","Präteritum","Präsens"],"correctAnswer":"Plusquamperfekt in the subordinate clause"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000125',1,'APPROVED','PUBLISHED',
'{"objectives":["Use advanced temporal clauses","Form clauses with seit/seitdem/sobald/kaum","Express nuanced time relationships"],"explanation":{"intro":"Advanced temporal conjunctions allow precise expression of time relationships beyond simple wenn/als/bevor/nachdem.","culturalNote":"Precision in expressing time is culturally valued in Germany. The correct use of seit/seitdem, sobald, kaum dass, bis, solange marks advanced German proficiency."},"examples":[{"german":"Seitdem er umgezogen ist, sehen wir uns seltener.","english":"Since he moved, we see each other less often."},{"german":"Sobald ich fertig bin, melde ich mich bei dir.","english":"As soon as I am finished, I''ll get in touch with you."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can use advanced temporal conjunctions to express precise time relationships."}}',
'{"items":[{"word":"seitdem","translation":"since (conjunction)","pronunciation":"ZYT-daym","example":"Seitdem er weg ist."},{"word":"sobald","translation":"as soon as","pronunciation":"zo-BALT","example":"Sobald ich fertig bin."},{"word":"solange","translation":"as long as","pronunciation":"zo-LANG-eh","example":"Solange du da bist."},{"word":"kaum dass","translation":"hardly/scarcely had","pronunciation":"kowm dahs","example":"Kaum dass er ankam."},{"word":"bis","translation":"until (conjunction)","pronunciation":"bis","example":"Bis er kommt."},{"word":"während","translation":"while (conjunction)","pronunciation":"VÄY-rent","example":"Während er schläft."}]}',
'{"title":"Sobald — as soon as (temporal conjunction)","pattern":"sobald + verb-final clause (as soon as — immediate response when condition met)","explanation":"Sobald = as soon as — the main clause action happens immediately when the condition is met. Sobald ich fertig bin, komme ich = As soon as I am finished, I will come. Tense: sobald clause uses present for future (not future tense): sobald er kommt (not sobald er kommen wird). Compare: als (when — past, one-time), wenn (when — future/habitual), sobald (as soon as — immediate response on completion).","examples":[{"sentence":"Sobald das Ergebnis feststeht, informiere ich Sie.","translation":"As soon as the result is known, I will inform you."},{"sentence":"Ruf mich an, sobald du angekommen bist.","translation":"Call me as soon as you have arrived."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Solange'' means?","options":["as long as","while","until","as soon as"],"correctAnswer":"as long as"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Since he moved, we see each other less often.","options":["Seitdem er umgezogen ist, sehen wir uns seltener.","Er ist umgezogen und wir sehen uns weniger.","Seit dem Umzug treffen wir uns selten.","Wir sehen uns seltener jetzt."],"correctAnswer":"Seitdem er umgezogen ist, sehen wir uns seltener."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sobald das Ergebnis feststeht, ___ ich Sie.","options":["informiere","informiert","informieren","werde informieren"],"correctAnswer":"informiere"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Call me as soon as you have arrived","wordBankItems":["Ruf","mich","an",",","sobald","du","angekommen","bist","."],"correctAnswer":"Ruf mich an , sobald du angekommen bist ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"In sobald clauses, future meaning is expressed with?","options":["present tense","future tense","Konjunktiv","Plusquamperfekt"],"correctAnswer":"present tense"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000126',1,'APPROVED','PUBLISHED',
'{"objectives":["Form relative clauses with prepositions","Use Präpositionaladverbien in relative clauses","Handle wobei/wofür/wozu/womit"],"explanation":{"intro":"Relative clauses with prepositions use wo- compounds (wobei, wofür, womit, wozu) for things, and preposition + dem/der for people.","culturalNote":"These constructions mark advanced German — native speakers use them freely but learners often avoid them. Mastering wo-compounds is essential for B1/B2 reading comprehension."},"examples":[{"german":"Das ist das Problem, womit wir uns am meisten beschäftigen.","english":"That is the problem that we deal with the most."},{"german":"Er zeigte mir das Werkzeug, mit dem er das Modell gebaut hatte.","english":"He showed me the tool with which he had built the model."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can form relative clauses with prepositions using wo-compounds and prepositional phrases."}}',
'{"items":[{"word":"womit","translation":"with which","pronunciation":"vo-MIT","example":"Das Werkzeug, womit."},{"word":"wofür","translation":"for which","pronunciation":"vo-FÜR","example":"Das Projekt, wofür."},{"word":"wobei","translation":"in/during which","pronunciation":"vo-BY","example":"Der Moment, wobei."},{"word":"wozu","translation":"to which/for which purpose","pronunciation":"vo-TSOO","example":"Der Grund, wozu."},{"word":"worüber","translation":"about which","pronunciation":"vo-RÜ-ber","example":"Das Thema, worüber."},{"word":"sich beschäftigen mit","translation":"to deal with/occupy oneself with","pronunciation":"zikh beh-SHÄF-tee-gen mit","example":"Sich mit etwas beschäftigen."}]}',
'{"title":"Wo-compounds in relative clauses — womit, wofür, wobei, wozu","pattern":"das Ding, womit/wofür/wobei/wozu + verb-final clause (thing-relative with preposition)","explanation":"When a relative pronoun refers to a thing and needs a preposition: use wo- + preposition. Das Thema, über das = Das Thema, worüber. Rules: wo- before vowels adds r: worüber, worin, worauf. For people: use prep + dem/der/denen. Examples: Der Mann, mit dem = the man with whom. Das Buch, worüber = the book about which. The wo-compound is more elegant but prep + dem/der is also correct for things.","examples":[{"sentence":"Das ist das Ziel, worauf ich seit Jahren hinarbeite.","translation":"That is the goal I have been working towards for years."},{"sentence":"Das ist das Thema, worüber wir diskutiert haben.","translation":"That is the topic we discussed."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Womit'' means?","options":["with which","with whom","with what","by which"],"correctAnswer":"with which"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"That is the problem that we deal with the most.","options":["Das ist das Problem, womit wir uns am meisten beschäftigen.","Das ist unser größtes Problem.","Wir beschäftigen uns mit dem Problem.","Das Problem beschäftigt uns."],"correctAnswer":"Das ist das Problem, womit wir uns am meisten beschäftigen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das ist das Ziel, ___ ich seit Jahren hinarbeite.","options":["worauf","worüber","wofür","womit"],"correctAnswer":"worauf"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: That is the topic we discussed","wordBankItems":["Das","ist","das","Thema",",","worüber","wir","diskutiert","haben","."],"correctAnswer":"Das ist das Thema , worüber wir diskutiert haben ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"For people in relative clauses with prepositions, use?","options":["preposition + dem/der/denen","wo-compound","wo + person","der/die/das"],"correctAnswer":"preposition + dem/der/denen"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000127',1,'APPROVED','PUBLISHED',
'{"objectives":["Use infinitive constructions","Form um zu / ohne zu / anstatt zu","Express purpose, manner, and alternatives"],"explanation":{"intro":"Infinitive constructions with um zu, ohne zu, and anstatt zu express purpose, manner, and alternatives in German.","culturalNote":"These constructions are used constantly in German — mastering them removes the need for entire subordinate clauses and makes German writing and speech more elegant."},"examples":[{"german":"Er lernt Deutsch, um in Deutschland arbeiten zu können.","english":"He is learning German in order to be able to work in Germany."},{"german":"Sie verließ das Haus, ohne sich zu verabschieden.","english":"She left the house without saying goodbye."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can use um zu, ohne zu, and anstatt zu infinitive constructions fluently."}}',
'{"items":[{"word":"um ... zu + Infinitiv","translation":"in order to","pronunciation":"oom ... tsoo","example":"Um zu lernen."},{"word":"ohne ... zu + Infinitiv","translation":"without (doing)","pronunciation":"OH-neh ... tsoo","example":"Ohne zu fragen."},{"word":"anstatt ... zu + Infinitiv","translation":"instead of (doing)","pronunciation":"AN-shtat ... tsoo","example":"Anstatt zu warten."},{"word":"sich verabschieden","translation":"to say goodbye/take leave","pronunciation":"zikh fer-AP-shee-den","example":"Sich verabschieden."},{"word":"damit","translation":"so that (conjunction — different subjects)","pronunciation":"DAH-mit","example":"Damit er versteht."},{"word":"zwecks","translation":"for the purpose of (formal)","pronunciation":"tsveks","example":"Zwecks weiterer Prüfung."}]}',
'{"title":"Um zu / ohne zu / anstatt zu — infinitive clusters","pattern":"um + zu + Infinitiv (purpose), ohne + zu + Infinitiv (without doing), anstatt + zu + Infinitiv (instead of doing)","explanation":"Three key infinitive constructions: 1) Um...zu (purpose — same subject): Er lernt, um zu bestehen = He studies to pass. 2) Ohne...zu (without doing — same subject): ohne zu fragen = without asking. 3) Anstatt...zu (instead of — same subject): anstatt zu schlafen = instead of sleeping. IMPORTANT: same subject required. Different subjects → damit clause: Er spricht langsam, damit sie versteht = He speaks slowly so that she understands.","examples":[{"sentence":"Sie arbeitet hart, um ihre Ziele zu erreichen.","translation":"She works hard in order to achieve her goals."},{"sentence":"Er aß, ohne ein Wort zu sagen.","translation":"He ate without saying a word."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"When the subjects differ, instead of um...zu we use?","options":["damit","so dass","weil","dass"],"correctAnswer":"damit"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"He is learning German in order to be able to work in Germany.","options":["Er lernt Deutsch, um in Deutschland arbeiten zu können.","Er lernt Deutsch, weil er in Deutschland arbeiten will.","Er lernt für die Arbeit Deutsch.","In Deutschland muss man Deutsch können."],"correctAnswer":"Er lernt Deutsch, um in Deutschland arbeiten zu können."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sie verließ das Haus, ohne sich zu ___.","options":["verabschieden","verabschiedet","verabschiedet haben","verabschieden werden"],"correctAnswer":"verabschieden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She works hard in order to achieve her goals","wordBankItems":["Sie","arbeitet","hart",",","um","ihre","Ziele","zu","erreichen","."],"correctAnswer":"Sie arbeitet hart , um ihre Ziele zu erreichen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Anstatt zu schlafen'' means?","options":["instead of sleeping","instead of to sleep","rather than sleeping","in place of sleeping"],"correctAnswer":"instead of sleeping"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000128',1,'APPROVED','PUBLISHED',
'{"objectives":["Understand verb formation patterns","Use prefixes to form new verbs","Recognise separable vs. inseparable verbs"],"explanation":{"intro":"Word formation with verb prefixes (Verbpräfixe) lets you massively expand your vocabulary from known roots.","culturalNote":"German''s ability to form compound verbs is extensive. Prefixes change meaning systematically: ver- often intensifies or indicates error, zer- destroys, be- makes intransitive → transitive, ent- reverses or begins, er- achieves or begins."},"examples":[{"german":"Das Präfix ''ver-'' kann viele Bedeutungen haben: verlaufen (to get lost), versuchen (to try), verbessern (to improve).","english":"The prefix ''ver-'' can have many meanings: to get lost, to try, to improve."},{"german":"''Be-'' macht viele intransitive Verben transitiv: antworten (intransitive) → beantworten (transitive, takes accusative).","english":"''Be-'' makes many intransitive verbs transitive: answer → answer something."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can understand and use German verb prefix patterns to expand my vocabulary."}}',
'{"items":[{"word":"ver-","translation":"prefix with multiple meanings","pronunciation":"fer","example":"Verbessern, verlaufen."},{"word":"be-","translation":"prefix making verbs transitive","pronunciation":"beh","example":"Beantworten, bearbeiten."},{"word":"zer-","translation":"prefix meaning destruction","pronunciation":"tser","example":"Zerstören, zerbrechen."},{"word":"ent-","translation":"prefix meaning removal/beginning","pronunciation":"ent","example":"Entfernen, entscheiden."},{"word":"er-","translation":"prefix meaning achievement/beginning","pronunciation":"er","example":"Erreichen, erkennen."},{"word":"das Präfix","translation":"prefix","pronunciation":"dahs PRAY-fiks","example":"Das trennbare Präfix."}]}',
'{"title":"Verb prefix patterns — ver-, be-, zer-, ent-, er-","pattern":"Each inseparable prefix has predictable semantic effects on the verb root","explanation":"Inseparable prefixes (never separate: be-, ge-, er-, ver-, zer-, ent-, emp-, miss-) systematically change meaning: ver- = error (vertippen = to mistype), intensification (verbessern = to improve), process completion. Be- = transitivise (wohnen = to live → bewohnen = to inhabit [+acc]). Zer- = destruction (brechen = break → zerbrechen = break into pieces). Ent- = removal (fernen → entfernen) or beginning. Er- = achievement of result (reichen → erreichen = to reach/achieve).","examples":[{"sentence":"Er hat sich beim Tippen vertippt — jetzt muss er es korrigieren.","translation":"He made a typo — now he has to correct it."},{"sentence":"Das Glas ist zerbrochen.","translation":"The glass has broken into pieces."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"What does prefix ''zer-'' typically indicate?","options":["destruction/breaking apart","error","intensification","completion"],"correctAnswer":"destruction/breaking apart"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The prefix ''be-'' makes many intransitive verbs transitive: answer → answer something.","options":["''Be-'' macht viele intransitive Verben transitiv: antworten → beantworten.","Be- ist ein Präfix.","Verben haben Präfixe.","Be- ändert die Bedeutung."],"correctAnswer":"''Be-'' macht viele intransitive Verben transitiv: antworten → beantworten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Glas ist ___.","options":["zerbrochen","gebrochen","verbrochen","abgebrochen"],"correctAnswer":"zerbrochen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He made a typo — now he has to correct it","wordBankItems":["Er","hat","sich","vertippt","—","jetzt","muss","er","es","korrigieren","."],"correctAnswer":"Er hat sich vertippt — jetzt muss er es korrigieren ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"What does prefix ''er-'' typically express?","options":["achievement/result","error","removal","intensification"],"correctAnswer":"achievement/result"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000129',1,'APPROVED','PUBLISHED',
'{"objectives":["Understand noun formation patterns","Use suffixes to form nouns","Recognise Nominalstil in formal German"],"explanation":{"intro":"Noun formation (Nomenbildung) from verbs, adjectives, and other nouns expands vocabulary and enables formal German.","culturalNote":"German formal writing (Nominalstil) heavily uses nominalisations. This is a feature of Amtssprache, academic writing, and business German. Understanding it is essential for B1+ reading comprehension."},"examples":[{"german":"Die Entscheidung wurde getroffen — nicht ''man hat sich entschieden''.","english":"The decision was made — not ''they decided'' (nominalised style)."},{"german":"Durch die Verwendung von Substantiven wirkt der Text formeller.","english":"Through the use of nouns the text seems more formal."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can form nouns from verbs and adjectives and understand Nominalstil."}}',
'{"items":[{"word":"-ung suffix","translation":"forms feminine nouns from verbs","pronunciation":"oong","example":"Entscheidung, Wohnung."},{"word":"-heit/-keit suffix","translation":"forms feminine nouns from adjectives","pronunciation":"hyt/kyt","example":"Freiheit, Sicherheit."},{"word":"-schaft suffix","translation":"forms feminine group/state nouns","pronunciation":"shaft","example":"Gesellschaft, Freundschaft."},{"word":"-ling suffix","translation":"forms masculine nouns (often persons)","pronunciation":"ling","example":"Frühling, Lehrling."},{"word":"-nis suffix","translation":"forms neutral/feminine abstract nouns","pronunciation":"nis","example":"Ergebnis, Kenntnis."},{"word":"der Nominalstil","translation":"nominal/nominalized style","pronunciation":"dayr no-mee-NAHL-shteel","example":"Nominalstil verwenden."}]}',
'{"title":"Nomenbildung — noun formation suffixes","pattern":"Verb + -ung → feminine noun; Adjective + -heit/-keit → feminine noun; -schaft for groups","explanation":"-Ung from verbs: entscheiden→die Entscheidung, wohnen→die Wohnung (always feminine, add Umlaut if needed). -Heit/-keit from adjectives: frei→Freiheit, sicher→Sicherheit, möglich→Möglichkeit (always feminine). Rule: -heit after monosyllabic or ending in -ig/-lich/-sam, -keit elsewhere. -Schaft: group/state: die Gesellschaft, die Freundschaft. -Nis: neuter/feminine: das Ergebnis, die Kenntnis. Learning suffixes → learn gender systematically.","examples":[{"sentence":"Die Möglichkeit, Deutsch zu lernen, ist heute besser denn je.","translation":"The possibility of learning German is better today than ever."},{"sentence":"Seine Freundschaft bedeutet mir viel.","translation":"His friendship means a lot to me."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"What gender do nouns with ''-ung'' suffix always have?","options":["feminine (die)","masculine (der)","neuter (das)","mixed"],"correctAnswer":"feminine (die)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The decision was made — not ''they decided'' (nominalised style).","options":["Die Entscheidung wurde getroffen — nicht ''man hat sich entschieden''.","Man hat entschieden.","Eine Entscheidung.","Entschieden wurde."],"correctAnswer":"Die Entscheidung wurde getroffen — nicht ''man hat sich entschieden''."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die ___ von frei ist Freiheit.","options":["Nominalisierung","Substantivierung","Ableitung","Bildung"],"correctAnswer":"Nominalisierung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: His friendship means a lot to me","wordBankItems":["Seine","Freundschaft","bedeutet","mir","viel","."],"correctAnswer":"Seine Freundschaft bedeutet mir viel ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Möglichkeit'' is formed from?","options":["möglich + -keit","möglich + -heit","mögen + -ung","mögen + -keit"],"correctAnswer":"möglich + -keit"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000012a',1,'APPROVED','PUBLISHED',
'{"objectives":["Understand adjective formation","Use suffixes to form adjectives","Recognize derived adjectives in text"],"explanation":{"intro":"Adjective formation patterns let you derive adjectives from nouns and verbs, massively expanding reading comprehension.","culturalNote":"German adjectives can be derived from almost any noun or verb. Understanding the common suffixes helps decode unknown words — a key skill for B1 reading. Compound adjectives (benutzerfreundlich = user-friendly) are also common."},"examples":[{"german":"Das ist ein gefährliches Experiment — das Adjektiv kommt von ''Gefahr''.","english":"That is a dangerous experiment — the adjective comes from ''danger''."},{"german":"Ein umweltfreundliches Produkt schont die Natur.","english":"An eco-friendly product spares nature."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can form and recognise adjectives from nouns and verbs in German."}}',
'{"items":[{"word":"-lich suffix","translation":"forms adjectives (like, -ful, -ly)","pronunciation":"likh","example":"Freundlich, gefährlich."},{"word":"-ig suffix","translation":"forms adjectives (having, characterized by)","pronunciation":"ikh","example":"Mächtig, hungrig."},{"word":"-isch suffix","translation":"forms relational/ethnic adjectives","pronunciation":"ish","example":"Bayerisch, ironisch."},{"word":"-bar suffix","translation":"forms possibility adjectives (-able, -ible)","pronunciation":"bar","example":"Machbar, erkennbar."},{"word":"-los suffix","translation":"forms adjectives meaning without","pronunciation":"los","example":"Arbeitslos, hoffnungslos."},{"word":"-freundlich suffix","translation":"forms friendly/compatible adjectives","pronunciation":"FROIND-likh","example":"Umweltfreundlich."}]}',
'{"title":"Adjektiv-Suffixe — -lich, -ig, -isch, -bar, -los","pattern":"Suffix patterns for adjective formation from nouns and verbs","explanation":"-Lich (from nouns/adjectives): Gefahr→gefährlich, Freund→freundlich, Kind→kindlich. -Ig (having quality): Hunger→hungrig, Macht→mächtig, Mut→mutig. -Isch (relational/often negative): Bayern→bayerisch, Ironie→ironisch, Heimweh→heimwehisch. -Bar (feasible, -able): machen→machbar, erkennen→erkennbar, zählen→zählbar. -Los (without): Arbeit→arbeitslos, Hoffnung→hoffnungslos. Compound: Umwelt + freundlich→umweltfreundlich.","examples":[{"sentence":"Die Lösung ist machbar, wenn alle mitarbeiten.","translation":"The solution is feasible if everyone cooperates."},{"sentence":"Es ist hoffnungslos, alleine dagegen anzukämpfen.","translation":"It is hopeless to fight against it alone."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Arbeitslos'' is formed with which suffix?","options":["-los (without)","suffix -ig","suffix -lich","suffix -bar"],"correctAnswer":"-los (without)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"An eco-friendly product spares nature.","options":["Ein umweltfreundliches Produkt schont die Natur.","Das Produkt ist umweltfreundlich.","Umweltfreundlich schützt die Natur.","Das Produkt schadet nicht."],"correctAnswer":"Ein umweltfreundliches Produkt schont die Natur."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Lösung ist ___, wenn alle mitarbeiten.","options":["machbar","machbar zu sein","zu machen","gemacht"],"correctAnswer":"machbar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: It is hopeless to fight against it alone","wordBankItems":["Es","ist","hoffnungslos",",","alleine","dagegen","anzukämpfen","."],"correctAnswer":"Es ist hoffnungslos , alleine dagegen anzukämpfen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erkennbar'' means?","options":["recognisable","detectable","identifiable","observable"],"correctAnswer":"recognisable"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000012b',1,'APPROVED','PUBLISHED',
'{"objectives":["Use text cohesion devices","Write well-structured paragraphs","Connect ideas with discourse markers"],"explanation":{"intro":"Text grammar (Textgrammatik) covers cohesion devices — how sentences connect into coherent paragraphs and texts.","culturalNote":"German academic and formal writing requires explicit cohesion. Essays and reports use structured connectors. The ability to write coherent multi-paragraph texts with appropriate discourse markers is expected at B1+."},"examples":[{"german":"Zunächst soll erläutert werden, was unter Globalisierung zu verstehen ist.","english":"First, it should be explained what is to be understood by globalisation."},{"german":"Darüber hinaus zeigt sich, dass die Folgen weitreichend sind.","english":"Moreover, it is evident that the consequences are far-reaching."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can write cohesive, well-structured texts using German discourse markers."}}',
'{"items":[{"word":"zunächst","translation":"first/initially","pronunciation":"tsoo-NÄCHST","example":"Zunächst zu erwähnen."},{"word":"darüber hinaus","translation":"moreover/furthermore","pronunciation":"dah-RÜ-ber hih-NOWS","example":"Darüber hinaus."},{"word":"im Gegensatz dazu","translation":"in contrast to that","pronunciation":"im GAY-gen-zats DAH-tsoo","example":"Im Gegensatz dazu."},{"word":"abschließend","translation":"finally/in conclusion","pronunciation":"AP-shlee-send","example":"Abschließend lässt sich sagen."},{"word":"was ... angeht","translation":"as far as ... is concerned","pronunciation":"vas ... AN-gayt","example":"Was die Kosten angeht."},{"word":"weitreichend","translation":"far-reaching","pronunciation":"VYT-ry-khend","example":"Weitreichende Folgen."}]}',
'{"title":"Darüber hinaus — moreover/furthermore (discourse connector)","pattern":"darüber hinaus + main clause (moreover — adds point beyond what was already said)","explanation":"Darüber hinaus = moreover, furthermore, beyond that. Positions: sentence-initial (common): Darüber hinaus zeigt sich, dass... OR after verb: Es zeigt sich darüber hinaus, dass. Common academic connectors: zunächst (initially) → dann/außerdem (then/also) → im Gegensatz dazu (in contrast) → darüber hinaus (moreover) → abschließend (in conclusion) → zusammenfassend (to summarise).","examples":[{"sentence":"Das Projekt ist kostengünstig. Darüber hinaus ist es umweltfreundlich.","translation":"The project is cost-effective. Moreover it is environmentally friendly."},{"sentence":"Im Gegensatz dazu zeigt die Statistik ein anderes Bild.","translation":"In contrast, the statistics show a different picture."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Weitreichend'' means?","options":["far-reaching","wide-ranging","extensive","broad"],"correctAnswer":"far-reaching"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"First, it should be explained what is to be understood by globalisation.","options":["Zunächst soll erläutert werden, was unter Globalisierung zu verstehen ist.","Zuerst: Was ist Globalisierung?","Globalisierung soll erklärt werden.","Erstens definiert man Globalisierung."],"correctAnswer":"Zunächst soll erläutert werden, was unter Globalisierung zu verstehen ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Projekt ist kostengünstig. ___ ist es umweltfreundlich.","options":["Darüber hinaus","Im Gegensatz dazu","Abschließend","Zunächst"],"correctAnswer":"Darüber hinaus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In contrast, the statistics show a different picture","wordBankItems":["Im","Gegensatz","dazu","zeigt","die","Statistik","ein","anderes","Bild","."],"correctAnswer":"Im Gegensatz dazu zeigt die Statistik ein anderes Bild ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Abschließend'' in essay writing means?","options":["finally/in conclusion","ending","closing","last"],"correctAnswer":"finally/in conclusion"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000012c',1,'APPROVED','PUBLISHED',
'{"objectives":["Celebrate 300 German lessons","Consolidate B1 grammar knowledge","Preview B1 final stretch and B2"],"explanation":{"intro":"You have reached 300 German lessons! You are solidly in B1 territory — able to communicate on complex topics, write structured texts, and understand authentic German.","culturalNote":"At 300 lessons you can now: read German news articles with good comprehension, participate in group conversations, write formal emails and letters, understand German films and TV with some difficulty. You are genuinely functional in German!"},"examples":[{"german":"300 Lektionen geschafft! Das entspricht ungefähr 300 Stunden Lernzeit.","english":"300 lessons done! That corresponds to approximately 300 hours of learning time."},{"german":"Auf zu den letzten 100 B1-Lektionen und dann zu B2!","english":"On to the last 100 B1 lessons and then to B2!"}],"rewards":{"xp":200,"coins":100},"metadata":{"estimatedMinutes":20,"canDo":"I have completed 300 German lessons — I am a confident B1 learner!"}}',
'{"items":[{"word":"ungefähr","translation":"approximately","pronunciation":"OON-geh-fäyr","example":"Ungefähr 300 Stunden."},{"word":"entsprechen","translation":"to correspond to","pronunciation":"ent-SHPREH-khen","example":"Das entspricht B1."},{"word":"functional","translation":"functional","pronunciation":"funk-TSYOH-nahl","example":"Funktional sprechen."},{"word":"die Lernzeit","translation":"learning time","pronunciation":"dee LERN-tsyt","example":"Die Gesamtlernzeit."},{"word":"der Fortschritt","translation":"progress","pronunciation":"dayr FORT-shrit","example":"Große Fortschritte."},{"word":"konsolidieren","translation":"to consolidate","pronunciation":"kon-zo-lee-DEER-en","example":"Kenntnisse konsolidieren."}]}',
'{"title":"Geschafft — achieved/done (colloquial expression)","pattern":"geschafft! = done! achieved it! / etwas schaffen = to manage to do something","explanation":"Schaffen = to manage, to achieve (colloquial). 300 Lektionen geschafft! = 300 lessons done / achieved! Das schaffe ich! = I can do this! / I''ll manage! Das habe ich geschafft = I did it! Different from erschaffen (to create) and schöpfen (to create/draw). Es schaffen = to make it, to manage: Er hat es geschafft, pünktlich zu sein = He managed to be on time.","examples":[{"sentence":"Ich habe die Prüfung geschafft — ich bin so erleichtert!","translation":"I passed the exam — I''m so relieved!"},{"sentence":"Du schaffst das — ich glaube an dich!","translation":"You can do it — I believe in you!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ungefähr'' means?","options":["approximately","around","roughly","about"],"correctAnswer":"approximately"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"300 lessons done! That corresponds to approximately 300 hours of learning time.","options":["300 Lektionen geschafft! Das entspricht ungefähr 300 Stunden Lernzeit.","Ich habe 300 Lektionen gelernt.","300 Stunden Deutsch!","Das Lernen ist lang."],"correctAnswer":"300 Lektionen geschafft! Das entspricht ungefähr 300 Stunden Lernzeit."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich habe die Prüfung ___ — ich bin so erleichtert!","options":["geschafft","gemacht","bestanden","genommen"],"correctAnswer":"geschafft"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: You can do it — I believe in you!","wordBankItems":["Du","schaffst","das","—","ich","glaube","an","dich","!"],"correctAnswer":"Du schaffst das — ich glaube an dich !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Konsolidieren'' means?","options":["to consolidate","to confirm","to solidify","to reinforce"],"correctAnswer":"to consolidate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

